ALTER TABLE civic_people ADD COLUMN IF NOT EXISTS identity_source_verified boolean NOT NULL DEFAULT false;
CREATE OR REPLACE FUNCTION public.can_manage_service_area(_user uuid,_area text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user,'admin') AND EXISTS(SELECT 1 FROM admin_permissions a WHERE a.user_id=_user AND (a.is_super_admin OR _area=ANY(a.coverage_ids))) $$;
REVOKE ALL ON FUNCTION can_manage_service_area(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION can_manage_service_area(uuid,text) TO anon,authenticated,service_role;
ALTER POLICY "verified public people" ON civic_people USING((active AND (verification_status='verified' OR (identity_source_verified AND jurisdiction IS NOT NULL))) OR public.can_manage_service_area(auth.uid(),coverage_id));
ALTER POLICY "admins create people" ON civic_people WITH CHECK(public.can_manage_service_area(auth.uid(),coverage_id));
ALTER POLICY "admins edit people" ON civic_people USING(public.can_manage_service_area(auth.uid(),coverage_id)) WITH CHECK(public.can_manage_service_area(auth.uid(),coverage_id));
ALTER POLICY "admins manage coverage" ON civic_coverage USING(public.can_manage_service_area(auth.uid(),id)) WITH CHECK(public.can_manage_service_area(auth.uid(),id));
ALTER POLICY "admins manage authorities" ON civic_authorities USING(public.can_manage_service_area(auth.uid(),coverage_id)) WITH CHECK(public.can_manage_service_area(auth.uid(),coverage_id));
ALTER POLICY "admins manage wards" ON civic_wards USING(public.can_manage_service_area(auth.uid(),coverage_id)) WITH CHECK(public.can_manage_service_area(auth.uid(),coverage_id));
ALTER POLICY "Staff can read teams" ON civic_teams USING(public.is_staff(auth.uid()) AND public.can_access_service_area(auth.uid(),coverage_id));
CREATE OR REPLACE FUNCTION public.admin_create_area_team(_area text,_name text,_department text,_categories text[],_wards text[],_active boolean DEFAULT false) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF NOT public.can_manage_service_area(auth.uid(),_area) THEN RAISE EXCEPTION 'Service-area administrator required'; END IF; IF length(trim(_name))<3 OR length(trim(_department))<2 OR cardinality(_categories)=0 THEN RAISE EXCEPTION 'Team name, department and categories required'; END IF; IF EXISTS(SELECT 1 FROM unnest(_wards) w WHERE NOT EXISTS(SELECT 1 FROM civic_wards cw WHERE cw.identifier=w AND cw.coverage_id=_area AND cw.active)) THEN RAISE EXCEPTION 'Ward outside selected service area'; END IF; INSERT INTO civic_teams(name,department,categories,wards,active,coverage_id,updated_by) VALUES(_name,_department,_categories,_wards,_active,_area,auth.uid()) RETURNING id INTO result; INSERT INTO civic_directory_audit(table_name,record_id,action,actor_id,new_row) VALUES('civic_teams',result,'area_team_created',auth.uid(),jsonb_build_object('coverage_id',_area,'name',_name,'active',_active)); RETURN result; END $$;
REVOKE ALL ON FUNCTION admin_create_area_team(text,text,text,text[],text[],boolean) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION admin_create_area_team(text,text,text,text[],text[],boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_area_team_configuration() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND NOT public.can_manage_service_area(auth.uid(),NEW.coverage_id) THEN RAISE EXCEPTION 'Team configuration outside administrator service area'; END IF; IF TG_OP='UPDATE' AND OLD.coverage_id IS DISTINCT FROM NEW.coverage_id AND EXISTS(SELECT 1 FROM issues WHERE team_id=OLD.id) THEN RAISE EXCEPTION 'Assigned team service area cannot change'; END IF; IF NEW.supervisor_id IS NOT NULL AND NOT public.can_access_service_area(NEW.supervisor_id,NEW.coverage_id) THEN RAISE EXCEPTION 'Supervisor outside team service area'; END IF; RETURN NEW; END $$;
CREATE TRIGGER area_team_configuration_guard BEFORE INSERT OR UPDATE ON civic_teams FOR EACH ROW EXECUTE FUNCTION guard_area_team_configuration();
CREATE OR REPLACE FUNCTION public.guard_area_configuration() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.reporting_enabled AND NOT OLD.reporting_enabled AND NOT EXISTS(SELECT 1 FROM civic_wards WHERE coverage_id=NEW.id AND active AND verification_status='verified') THEN RAISE EXCEPTION 'Verified jurisdiction polygons required before activating reports'; END IF; RETURN NEW; END $$;
CREATE TRIGGER area_reporting_activation_guard BEFORE UPDATE ON civic_coverage FOR EACH ROW EXECUTE FUNCTION guard_area_configuration();